const express = require("express");
const app = express();
const port = process.env.PORT || 3000;

app.get("/api/sante", (req, res) => {
  res.json({ statut: "ok", heure: new Date().toISOString() });
});

app.listen(port, () => {
  console.log(`Serveur sur http://localhost:${port}`);
});
